def subtract(a, b):
    def clean(intervals):
        return [[s, e] for s, e in intervals if s < e]

    def merge(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals, key=lambda x: x[0])
        merged = [list(intervals[0])]
        for s, e in intervals[1:]:
            last = merged[-1]
            if s <= last[1]:
                if e > last[1]:
                    last[1] = e
            else:
                merged.append([s, e])
        return merged

    a_clean = clean(a)
    b_clean = clean(b)

    a_merged = merge(a_clean)
    b_merged = merge(b_clean)

    result = []

    for seg_start, seg_end in a_merged:
        cur = seg_start
        # find relevant b intervals overlapping this segment
        for bs, be in b_merged:
            if be <= cur:
                continue
            if bs >= seg_end:
                break
            # overlap portion
            if bs > cur:
                result.append([cur, min(bs, seg_end)])
            cur = max(cur, be)
            if cur >= seg_end:
                break
        if cur < seg_end:
            result.append([cur, seg_end])

    # final merge in case adjacent pieces touch (shouldn't happen due to gaps, but be safe)
    result = merge(result)
    return sorted(result)

